"""`.SVS alphamask parser`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.SVS alphamask parser'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Value', 'NodeSocketFloat')
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Value', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Value', 'NodeSocketFloat', default_value=1.0)
    t.socket('INPUT', 'Value', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Value', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (586.5247, 60.823784),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-743.9678, 62.996063),
    })
    t.node('ShaderNodeSeparateColor', 'Separate Color', props={
        'location': (-543.9678, -56.435463),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Math.002', props={
        'location': (368.33716, 52.771313),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.007', inputs={'Value_001': 1.0}, props={
        'location': (86.51221, 89.75276),
        'hide': True,
        'operation': 'MAXIMUM',
        'use_clamp': True,
    })
    t.node('ShaderNodeSeparateColor', 'Separate Color.001', props={
        'location': (-536.21814, 26.345514),
        'hide': True,
    })
    t.node('ShaderNodeClamp', 'Clamp', props={
        'location': (-531.9063, 93.328995),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Math', inputs={'Value': 1.0}, props={
        'location': (-361.93982, 27.97204),
        'width': 144.40483,
        'hide': True,
        'operation': 'SUBTRACT',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.001', inputs={'Value': 1.0}, props={
        'location': (-375.10095, -56.09193),
        'hide': True,
        'operation': 'SUBTRACT',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.003', inputs={'Value': 1.0}, props={
        'location': (40.919044, -33.177044),
        'hide': True,
        'operation': 'MINIMUM',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.008', inputs={'Value': 0.999, 'Value_001': 0.99}, props={
        'location': (-336.81506, 84.01253),
        'hide': True,
        'operation': 'LESS_THAN',
    })
    t.node('ShaderNodeMath', 'Math.004', inputs={'Value': 1.0}, props={
        'location': (-165.31642, -71.2357),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.005', inputs={'Value': 1.0}, props={
        'location': (-165.40462, 6.612877),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })

    t.link('Separate Color.001', 'Red', 'Math', 'Value_001')
    t.link('Math.008', 'Value', 'Math.007', 'Value')
    t.link('Separate Color', 'Red', 'Math.001', 'Value_001')
    t.link('Math.007', 'Value', 'Math.002', 'Value_001')
    t.link('Math.005', 'Value', 'Math.003', 'Value')
    t.link('Math.004', 'Value', 'Math.003', 'Value_001')
    t.link('Math', 'Value', 'Math.005', 'Value')
    t.link('Math.003', 'Value', 'Math.007', 'Value_001')
    t.link('Math.001', 'Value', 'Math.004', 'Value')
    t.link('Clamp', 'Result', 'Math.008', 'Value')
    t.link('Group Input', 0, 'Separate Color', 'Color')
    t.link('Group Input', 4, 'Math.004', 'Value_001')
    t.link('Group Input', 3, 'Clamp', 'Value')
    t.link('Group Input', 5, 'Math.005', 'Value_001')
    t.link('Group Input', 2, 'Separate Color.001', 'Color')
    t.link('Group Input', 1, 'Math.002', 'Value')
    t.link('Math.002', 'Value', 'Group Output', 'Value')
    return t
